import { existsSync } from "node:fs";
import { basename, join } from "node:path";
import type { PackManifest, PackSample } from "../types";

/** A pack as it stands in its folder: the manifest, and each sample's file name beside `pack.ts`. */
export type PackOnDisk = { manifest: PackManifest; files: Record<string, string> };

/** Runs after `pack.ts` is written, with its path: a game that formats its generated files formats it here. */
export type FormatHook = (file: string) => void | Promise<void>;

let reads = 0;

/**
 * Reads a pack back from the `pack.ts` in `dir` (`null` when there is none). The module is imported, not parsed: under
 * Bun each audio import resolves to the file's path, so every value and file name is what the module says, however a
 * formatter has laid the text out. Each read imports afresh (a query defeats the module cache).
 */
export async function readManifest(dir: string): Promise<PackOnDisk | null> {
  const file = join(dir, "pack.ts");
  if (!existsSync(file)) return null;
  let mod: { pack?: PackManifest };
  try {
    // A query on the path, not on a file URL: Bun 1.4 keys its module cache by a file URL without its query.
    mod = await import(`${file}?read=${++reads}`);
  } catch (e) {
    throw new Error(`${file} cannot be imported: ${e instanceof Error ? e.message : String(e)}`);
  }
  const pack = mod.pack;
  if (!pack || typeof pack !== "object" || typeof pack.samples !== "object")
    throw new Error(`${file} exports no \`pack\` manifest`);
  const files: Record<string, string> = {};
  const samples: Record<string, PackSample> = {};
  for (const [name, s] of Object.entries(pack.samples)) {
    files[name] = basename(
      String(s.url)
        .replace(/[?#].*$/, "")
        .replaceAll("\\", "/"),
    );
    samples[name] = { ...s, url: files[name] };
  }
  return { manifest: { ...pack, samples }, files };
}

/** Writes `pack.ts` into `dir` as `buildPack` would, then runs `format` over it. */
export async function writeManifest(
  dir: string,
  manifest: PackManifest,
  files: Readonly<Record<string, string>>,
  format?: FormatHook,
): Promise<string> {
  const file = join(dir, "pack.ts");
  await Bun.write(file, manifestSource(manifest, files));
  await format?.(file);
  return file;
}

const q = (s: string) => JSON.stringify(s);
const round = (v: number, places: number) => Number(v.toFixed(places));

/**
 * The text of `pack.ts`: a static import of each encoded file's URL (so a bundler fingerprints it) and the typed
 * manifest. `files` maps a sample's name to its file name beside `pack.ts`.
 */
export function manifestSource(manifest: PackManifest, files: Readonly<Record<string, string>>): string {
  const names = Object.keys(manifest.samples).sort();
  const lines = [
    "// Generated by watchpot/sound/pack from the source folder: edit the source and rebuild, not this file.",
    'import type { PackManifest } from "watchpot/sound";',
    ...names.map((n, i) => `import s${i} from ${q(`./${files[n]}`)};`),
    "",
    "export const pack: PackManifest = {",
    `  name: ${q(manifest.name)},`,
  ];
  if (manifest.tempo !== undefined) lines.push(`  tempo: ${manifest.tempo},`);
  if (manifest.key !== undefined) lines.push(`  key: ${q(manifest.key)},`);
  lines.push("  samples: {");
  names.forEach((n, i) => {
    const s = manifest.samples[n] as PackSample;
    const fields = [
      `url: s${i}`,
      `seconds: ${round(s.seconds, 5)}`,
      `channels: ${s.channels}`,
      `lufs: ${round(s.lufs, 2)}`,
      `peak: ${round(s.peak, 5)}`,
      `kind: ${q(s.kind)}`,
    ];
    if (s.rootHz !== undefined) fields.push(`rootHz: ${round(s.rootHz, 2)}`);
    if (s.bars !== undefined) fields.push(`bars: ${s.bars}`);
    if (s.source !== undefined) fields.push(`source: ${q(s.source)}`);
    lines.push(`    ${q(n)}: { ${fields.join(", ")} },`);
  });
  lines.push("  },", "};", "");
  return lines.join("\n");
}
